import gurobipy
from gurobipy import GRB

def solve_problem():
    table_id = 'file_0_view_0'
    table = None
    for tbl in CSVQA_DATA['tables']:
        if tbl.get('table_id') == table_id:
            table = tbl
            break
    if table is None:
        raise ValueError(f'Table {table_id} not found in CSVQA_DATA')
    records = table.get('records', [])
    if not records:
        raise ValueError(f'No records found in table {table_id}')
    I = []
    g = {}
    c = {}
    for rec in records:
        vals = rec['values']
        option = vals['option']
        if option in I:
            continue
        I.append(option)
        try:
            g_val = int(vals['gen_per_lot'])
        except (ValueError, TypeError):
            raise ValueError(f'Invalid gen_per_lot for option {option}')
        try:
            c_val = float(vals['cost_per_lot'])
        except (ValueError, TypeError):
            raise ValueError(f'Invalid cost_per_lot for option {option}')
        g[option] = g_val
        c[option] = c_val
    for opt in I:
        if opt not in g or opt not in c:
            raise ValueError(f'Missing parameters for option {opt}')
    D = 200
    m = gurobipy.Model()
    m.setParam('MIPGap', 1e-06)
    x = m.addVars(I, lb=0, vtype=GRB.INTEGER, name='')
    m.setObjective(gurobipy.quicksum((c[i] * x[i] for i in I)), GRB.MINIMIZE)
    m.addConstr(gurobipy.quicksum((g[i] * x[i] for i in I)) >= D, name='demand')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal: {m.ObjVal}')
        for var in m.getVars():
            print(f'{var.VarName}: {var.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = solve_problem()
